arguments.file_text:
@page "/apply"
@using sv_b55d721ac06847daabcda33afd90742f.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (stepIndex < CurrentStep)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (i < StepNames.Length - 1)
            {
                <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (Errors.Count > 0)
    {
        <div class="validation-errors">
            @foreach (var error in Errors)
            {
                <p>@error</p>
            }
        </div>
    }

    @* Step Content *@
    @if (!IsSubmitted)
    {
        @switch (CurrentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReviewSubmit()
                break;
        }
    }
    else
    {
        <div class="confirmation">
            <h2>&#10003; Application Submitted!</h2>
            <p>Your application has been successfully submitted.</p>
            <p><strong>Application ID: @SubmittedApplicationId</strong></p>
            <p>We will review your application and get back to you soon.</p>
        </div>
    }
</div>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; }
    private List<string> Errors { get; set; } = new();
    private bool IsSubmitting { get; set; }
    private bool IsSubmitted { get; set; }
    private int SubmittedApplicationId { get; set; }

    // Step 1 - Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2 - Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string CoverLetter { get; set; } = "";
    private const int MaxCoverLetterLength = 2000;

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "future";
    }

    private void NavigateToStep(int step)
    {
        if (step < CurrentStep)
        {
            Errors.Clear();
            CurrentStep = step;
        }
    }

    private async Task NextStep()
    {
        Errors.Clear();

        if (!await ValidateCurrentStep())
            return;

        CurrentStep++;
    }

    private void PreviousStep()
    {
        Errors.Clear();
        if (CurrentStep > 0) CurrentStep--;
    }

    private async Task<bool> ValidateCurrentStep()
    {
        switch (CurrentStep)
        {
            case 0:
                if (string.IsNullOrWhiteSpace(FullName)) Errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(Email)) Errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(Phone)) Errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(Address)) Errors.Add("Address is required.");
                if (Errors.Count == 0)
                {
                    var emailValid = await ApplicationService.ValidateEmailAsync(Email);
                    if (!emailValid) Errors.Add("Please enter a valid email address.");
                }
                break;
            case 1:
                foreach (var (entry, idx) in WorkEntries.Select((e, i) => (e, i)))
                {
                    if (string.IsNullOrWhiteSpace(entry.Company)) Errors.Add($"Position {idx + 1}: Company name is required.");
                    if (string.IsNullOrWhiteSpace(entry.Title)) Errors.Add($"Position {idx + 1}: Job title is required.");
                    if (entry.StartDate == default) Errors.Add($"Position {idx + 1}: Start date is required.");
                }
                break;
            case 2:
                foreach (var (reference, idx) in References.Select((r, i) => (r, i)))
                {
                    if (string.IsNullOrWhiteSpace(reference.Name)) Errors.Add($"Reference {idx + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(reference.Email)) Errors.Add($"Reference {idx + 1}: Email is required.");
                }
                break;
            case 3:
                if (string.IsNullOrWhiteSpace(CoverLetter)) Errors.Add("Cover letter is required.");
                if (CoverLetter.Length > MaxCoverLetterLength) Errors.Add($"Cover letter must be {MaxCoverLetterLength} characters or less.");
                break;
        }
        return Errors.Count == 0;
    }

    private async Task SubmitApplication()
    {
        IsSubmitting = true;
        Errors.Clear();

        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = References.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(personal, workHistory, references, CoverLetter);
            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            Errors.Add($"Submission failed: {ex.Message}");
        }
        finally
        {
            IsSubmitting = false;
        }
    }

    // Work entry add/remove
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(WorkEntryModel entry)
    {
        if (WorkEntries.Count > 1) WorkEntries.Remove(entry);
    }

    // Reference add/remove
    private void AddReference()
    {
        if (References.Count < 3) References.Add(new ReferenceModel());
    }

    private void RemoveReference(ReferenceModel reference)
    {
        if (References.Count > 2) References.Remove(reference);
    }

    // View models
    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    // Render fragments
    private RenderFragment RenderPersonalInfo() => __builder =>
    {
        <div class="step-content">
            <h2>Personal Information</h2>
            <div class="form-group">
                <label for="fullName">Full Name *</label>
                <input id="fullName" type="text" @bind="FullName" placeholder="John Doe" />
            </div>
            <div class="form-group">
                <label for="email">Email *</label>
                <input id="email" type="email" @bind="Email" placeholder="john@example.com" />
            </div>
            <div class="form-group">
                <label for="phone">Phone *</label>
                <input id="phone" type="tel" @bind="Phone" placeholder="(555) 123-4567" />
            </div>
            <div class="form-group">
                <label for="address">Address *</label>
                <input id="address" type="text" @bind="Address" placeholder="123 Main St, City, State ZIP" />
            </div>
            <div class="step-buttons">
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };

    private RenderFragment RenderWorkHistory() => __builder =>
    {
        <div class="step-content">
            <h2>Work History</h2>
            @for (int i = 0; i < WorkEntries.Count; i++)
            {
                var entry = WorkEntries[i];
                var index = i;
                <div class="work-entry-card">
                    <div class="entry-header">
                        <h3>Position @(index + 1)</h3>
                        @if (WorkEntries.Count > 1)
                        {
                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(entry)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Company Name *</label>
                        <input type="text" @bind="entry.Company" placeholder="Company Inc." />
                    </div>
                    <div class="form-group">
                        <label>Job Title *</label>
                        <input type="text" @bind="entry.Title" placeholder="Software Engineer" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Start Date *</label>
                            <input type="date" @bind="entry.StartDate" />
                        </div>
                        <div class="form-group">
                            <label>End Date</label>
                            <input type="date" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                            <label class="checkbox-label">
                                <input type="checkbox" @bind="entry.IsCurrent" /> Currently working here
                            </label>
                        </div>
                    </div>
                    <div class="form-group">
                        <label>Description</label>
                        <textarea @bind="entry.Description" placeholder="Describe your responsibilities..." rows="3"></textarea>
                    </div>
                </div>
            }
            <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };

    private RenderFragment RenderReferences() => __builder =>
    {
        <div class="step-content">
            <h2>References</h2>
            @for (int i = 0; i < References.Count; i++)
            {
                var reference = References[i];
                var index = i;
                <div class="reference-card">
                    <div class="entry-header">
                        <h3>Reference @(index + 1)</h3>
                        @if (References.Count > 2)
                        {
                            <button class="btn-remove" @onclick="() => RemoveReference(reference)">Remove</button>
                        }
                    </div>
                    <div class="form-group">
                        <label>Name *</label>
                        <input type="text" @bind="reference.Name" placeholder="Jane Smith" />
                    </div>
                    <div class="form-group">
                        <label>Relationship</label>
                        <input type="text" @bind="reference.Relationship" placeholder="Former Manager" />
                    </div>
                    <div class="form-row">
                        <div class="form-group">
                            <label>Email *</label>
                            <input type="email" @bind="reference.Email" placeholder="jane@example.com" />
                        </div>
                        <div class="form-group">
                            <label>Phone</label>
                            <input type="tel" @bind="reference.Phone" placeholder="(555) 987-6543" />
                        </div>
                    </div>
                </div>
            }
            @if (References.Count < 3)
            {
                <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
            }
            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };

    private RenderFragment RenderCoverLetter() => __builder =>
    {
        <div class="step-content">
            <h2>Cover Letter</h2>
            <div class="form-group">
                <label for="coverLetter">Write your cover letter *</label>
                <textarea id="coverLetter" @bind="CoverLetter" @bind:event="oninput" rows="12"
                    placeholder="Dear Hiring Manager..." maxlength="@MaxCoverLetterLength"></textarea>
                <div class="character-count @(CoverLetter.Length > MaxCoverLetterLength ? "over-limit" : "")">
                    @CoverLetter.Length / @MaxCoverLetterLength characters
                </div>
            </div>
            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-next" @onclick="NextStep">Next</button>
            </div>
        </div>
    };

    private RenderFragment RenderReviewSubmit() => __builder =>
    {
        <div class="step-content">
            <h2>Review & Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <button class="btn-edit" @onclick="() => { CurrentStep = 0; }">Edit</button>
                </div>
                <dl>
                    <dt>Full Name</dt><dd>@FullName</dd>
                    <dt>Email</dt><dd>@Email</dd>
                    <dt>Phone</dt><dd>@Phone</dd>
                    <dt>Address</dt><dd>@Address</dd>
                </dl>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <button class="btn-edit" @onclick="() => { CurrentStep = 1; }">Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="review-entry">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>References</h3>
                    <button class="btn-edit" @onclick="() => { CurrentStep = 2; }">Edit</button>
                </div>
                @foreach (var reference in References)
                {
                    <div class="review-entry">
                        <strong>@reference.Name</strong> (@reference.Relationship)<br />
                        @reference.Email @(!string.IsNullOrWhiteSpace(reference.Phone) ? $"| {reference.Phone}" : "")
                    </div>
                }
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Cover Letter</h3>
                    <button class="btn-edit" @onclick="() => { CurrentStep = 3; }">Edit</button>
                </div>
                <p class="cover-letter-preview">@CoverLetter</p>
            </div>

            <div class="step-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-submit" @onclick="SubmitApplication" disabled="@IsSubmitting">
                    @(IsSubmitting ? "Submitting..." : "Submit Application")
                </button>
            </div>
        </div>
    };
}

