toolArgs.file_text:
.application-container {
    max-width: 800px;
    margin: 2rem auto;
    padding: 0 1.5rem;
}

.application-container h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    flex-wrap: wrap;
    gap: 0.25rem;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.3s;
}

.step.active .step-circle {
    border-color: #4361ee;
    background: #4361ee;
    color: #fff;
}

.step.completed .step-circle {
    border-color: #2ec4b6;
    background: #2ec4b6;
    color: #fff;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #666;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    min-width: 20px;
    max-width: 60px;
    margin-bottom: 1.2rem;
}

.step-connector.completed {
    background: #2ec4b6;
}

/* Form Styles */
.step-content {
    background: #fff;
    border-radius: 8px;
    padding: 2rem;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.4rem;
    font-weight: normal !important;
    font-size: 0.85rem !important;
    cursor: pointer;
}

.checkbox-label input[type="checkbox"] {
    width: auto;
}

/* Cards for entries */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #444;
}

/* Buttons */
.step-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    gap: 1rem;
}

.btn-next,
.btn-back,
.btn-submit,
.btn-add,
.btn-remove,
.btn-edit {
    padding: 0.6rem 1.5rem;
    border: none;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    transition: background 0.2s, opacity 0.2s;
}

.btn-next {
    background: #4361ee;
    color: #fff;
    margin-left: auto;
}

.btn-next:hover {
    background: #3651d4;
}

.btn-back {
    background: #e8e8e8;
    color: #333;
}

.btn-back:hover {
    background: #ddd;
}

.btn-submit {
    background: #2ec4b6;
    color: #fff;
    font-weight: 600;
}

.btn-submit:hover:not(:disabled) {
    background: #25a99d;
}

.btn-submit:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-add {
    background: #f0f0f0;
    color: #4361ee;
    font-weight: 500;
    margin-bottom: 1rem;
}

.btn-add:hover {
    background: #e4e4e4;
}

.btn-remove {
    background: #fee;
    color: #c0392b;
    font-size: 0.8rem;
    padding: 0.4rem 0.8rem;
}

.btn-remove:hover {
    background: #fdd;
}

.btn-edit {
    background: transparent;
    color: #4361ee;
    padding: 0.3rem 0.8rem;
    border: 1px solid #4361ee;
    font-size: 0.8rem;
}

.btn-edit:hover {
    background: #4361ee;
    color: #fff;
}

/* Character Count */
.character-count {
    text-align: right;
    font-size: 0.8rem;
    color: #888;
    margin-top: 0.4rem;
}

.character-count.over-limit {
    color: #c0392b;
    font-weight: 600;
}

/* Validation Errors */
.validation-errors {
    background: #fee;
    border: 1px solid #fcc;
    border-radius: 6px;
    padding: 1rem;
    margin-bottom: 1.5rem;
}

.validation-errors p {
    margin: 0.3rem 0;
    color: #c0392b;
    font-size: 0.9rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #1a1a2e;
}

.review-section dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.4rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #666;
    font-size: 0.9rem;
}

.review-section dd {
    margin: 0;
    font-size: 0.9rem;
}

.review-entry {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
    font-size: 0.9rem;
}

.review-entry:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    font-size: 0.9rem;
    color: #444;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: #fff;
    border-radius: 8px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.08);
}

.confirmation h2 {
    color: #2ec4b6;
    font-size: 1.8rem;
}

.confirmation p {
    color: #555;
    font-size: 1.05rem;
}

